"""Immutable final reports and complete artifact SHA-256 index."""
from pathlib import Path
import csv,json,hashlib,datetime,math,collections
ROOT=Path(__file__).resolve().parents[3];OUT=Path(__file__).resolve().parent

def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
 return h.hexdigest()
def read(name):
 with (OUT/name).open() as f:return list(csv.DictReader(f))
def js(name):return json.loads((OUT/name).read_text())
def value(x):
 if x is None:return 'N/A'
 try:
  z=float(x)
  if not math.isfinite(z):return 'N/A'
  return f'{z:.8g}'
 except (ValueError,TypeError):return str(x).replace('|','\\|').replace('\n',' ')
def table(rows,cols):
 return '| '+' | '.join(cols)+' |\n| '+' | '.join(['---']*len(cols))+' |\n'+'\n'.join('| '+' | '.join(value(r.get(c,'')) for c in cols)+' |' for r in rows)+'\n'
def link(name):return '['+name+']('+name+')'
def write(name,text):
 with (OUT/name).open('x') as f:f.write(text)
def main():
 assert js('QA_STEP26.json')['all_pass'];assert js('INDEPENDENT_VAL_SELECTION.json')['all_pass'];assert js('INDEPENDENT_TEST_VALIDATION.json')['all_pass'];assert js('MANUSCRIPT_ARTIFACTS_COMPLETE.json');assert js('COMPARISON_TABLES_COMPLETE.json')
 protocol=js('PROTOCOL_SHA256.json');lock=js('SELECTION_LOCK_SHA256.json');assert sha(OUT/'PROTOCOL_STEP26.md')==protocol['sha256'];assert sha(OUT/'SELECTION_LOCK.csv')==lock['sha256']
 selection=read('SELECTION_LOCK.csv');repro=read('REPRODUCTION_STEP26.csv');testrepro=read('ORIGINAL_GRID_TEST_REPRODUCTION.csv');inv=read('INVENTORY_STEP26.csv');metrics=read('TEST_METRICS_STEP26.csv');wide=read('OLD_NEW_TEST_METRICS_STEP26.csv');impact=read('IMPACT_STEP26_COMPLETE.csv');preserve=js('FINAL_PREEXISTING_PRESERVATION_CHECK.json');valid=js('INDEPENDENT_VAL_SELECTION.json');testvalid=js('INDEPENDENT_TEST_VALIDATION.json');qa=js('QA_STEP26.json');env=js('ENVIRONMENT_STEP26.json')
 discrepancies=[r for r in testrepro if r['classification']=='DIFFERENT'];changed=sum(float(r['old_alpha'])!=float(r['selected_alpha']) for r in selection);boundary=[r for r in selection if r['interior']=='False'];elapsed=(datetime.datetime.now(datetime.timezone.utc)-datetime.datetime.fromisoformat(protocol['registered_utc'])).total_seconds();impactcounts=collections.Counter(r['qualitative_statement'] for r in impact)
 # Independent validator report: numerical checks plus explicit source-reproduction caveat.
 v=['# VALIDATION_STEP26\n', '## BLOCKING\n', 'None for independent VAL selection or W3 TEST metric recomputation. The nine archived W3 O original-grid TEST replays remain DIFFERENT; this provenance limitation is retained below rather than treated as passing evidence. Three input-file paths were relocated by the user; their bytes match exactly.\n', '## Independent numerical recomputation\n', 'The selection validator uses a separate direct sklearn Ridge loop, not the AST selection wrapper. It rebuilds all TRAIN/VAL features with the authoritative normalizer/flattening functions, fits every locked candidate for every one of the 33 cells, computes VAL squared errors independently, and takes the first strict ascending-grid minimum. Its TEST deserializers remain guarded. Every alpha and every VAL candidate MSE agrees exactly (maximum MSE difference 0).\n',table(valid['cells'],['cell_id','recorded_alpha','independent_alpha','alpha_equal','max_val_mse_discrepancy']), 'W3 TEST validation uses Python math.fsum of per-observation squared errors and scipy.stats.spearmanr separately for each date. It covers all 21 W3 Ridge fits (18 raw and3 CS), both archived-old and selected-new forecasts, giving42 checks. It preserves the original 1e-12 within-date variance guard. No non-Ridge model is evaluated.\n',table(read('INDEPENDENT_W3_TEST_METRICS.csv'),['cell_id','arm','mse_independent','mse_discrepancy','rank_ic_independent','rank_ic_discrepancy','passed']),f"Maximum TEST MSE discrepancy {testvalid['max_mse_discrepancy']:.17g}; maximum Rank IC discrepancy {testvalid['max_rank_ic_discrepancy']:.17g}.\n", '## Original-grid reproduction caveat\n',table(discrepancies,['cell_id','max_abs_delta','classification']), 'These archived W3 O fits have no stored VAL/TRAIN predictions or fitted object. Their recorded alphas were recovered from the formal MAIN V2 summary and all nine alphas reproduce; only the post-lock TEST predictions fail the strict replay tolerance. No solver/thread search or selective refit was performed after TEST. The user’s B1 stopping condition is for DIFFERENT stored-VAL cells; none occurred.\n','## Additional audit\n',table(qa['checks'],['check','passed','detail']), 'The original Ridge portfolio replay covers 156 reported original metric rows; maximum discrepancy across Sharpe, annual turnover, drawdown and certainty equivalents is4.9856101469458736e-9. The extra12 C top3 strategy/cost rows per arm have no reported Step16 source and are kept as nonprimary audit rows. Raw non-Ridge forecast-skill and shrinkage fields were asserted unchanged.\n','## Gates and preservation\n',f"Protocol SHA-256 `{protocol['sha256']}`; selection-lock SHA-256 `{lock['sha256']}`. The first TEST deserialization follows TEST_UNLOCK.json, which references the sealed all 33-cell lock.\n",f"The final preservation check covers{preserve['n_records']:,} pre-existing path records. {preserve['n_records']-len(preserve['issues']):,} remain at their original paths with unchanged bytes/link targets. The only three missing old paths are revision_work/step26/.DS_Store and the two input DOCX files, moved by the user to revision_work/inputs/step26/; all three destination SHA-256 values exactly match their original bytes. No other original file changed. See {link('FINAL_PREEXISTING_PRESERVATION_CHECK.json')} and the full per-path JSONL ledger.\n",'## Artifacts\n', 'Independent source: validate_selection26_v2.py and validate_test26.py. Machine-readable results: INDEPENDENT_VAL_SELECTION.json, INDEPENDENT_W3_TEST_METRICS.csv, INDEPENDENT_TEST_VALIDATION.json, QA_STEP26.csv. Final hashes, including this report, are in FINAL_ARTIFACT_SHA256.csv.\n']
 write('VALIDATION_STEP26.md','\n'.join(v))
 # One complete pre-report file list; final detached manifest below adds the report itself.
 files=[p for p in sorted(OUT.rglob('*')) if p.is_file()]
 manifest=[dict(path=str(p.relative_to(OUT)),bytes=p.stat().st_size,sha256=sha(p)) for p in files]
 with (OUT/'FILES_BEFORE_REPORT_STEP26.csv').open('x',newline='') as f:
  w=csv.DictWriter(f,fieldnames=['path','bytes','sha256']);w.writeheader();w.writerows(manifest)
 r=['# BLOCKING\n','No user-specified stored-VAL or runtime stopping gate failed. Two qualifications prevent an unqualified reproduction/preservation sign-off:\n', '- **Archived W3 price-level reproduction:** all 9 deferred original-grid TEST comparisons are DIFFERENT (maximum absolute differences1.09e-5–9.85e-4). Their original selected alphas are known and reproduced; their TRAIN/VAL forecasts and fitted objects are unavailable. Results are reported without a solver search, selective rerun, or a claim that the O changes isolate only the penalty numerically.\n', '- **User-side file relocation:** the two manuscript DOCX files and their .DS_Store moved from revision_work/step26/ to revision_work/inputs/step26/ during the session. Their bytes are unchanged. Every other pre-existing path passed the final hash check. The assistant wrote only in this new Step26 directory.\n', '# Step26 Ridge extended penalty grid\n',f"Generated UTC {datetime.datetime.now(datetime.timezone.utc).isoformat()}. All33 inventoried Ridge cells are retained. No non-Ridge estimator was trained, inferred, or re-evaluated; existing non-Ridge raw results are copied, with joint Holm correction recomputed where required.\n",'## Protocol and gates\n',f"Protocol SHA-256: `{protocol['sha256']}`. Selection-lock SHA-256: `{lock['sha256']}`. The protocol was written and hashed before dataset loading, fitting or numerical analysis. Original grid[.1,1,10,100]; initial extended grid1e-2 through1e6 by decades; symmetric two-decade extension, lower cap1e-6, upper cap1e12; strict ascending-grid comparison gives the smaller alpha on an exact tie. The original Ridge constructor/default solver, intercept, float32 features/targets and TRAIN-only normalizer are unchanged. Models fit TRAIN only.\n",f"First-three-cell projection {js('TIMING_GATE.json')['projection_seconds']:.3f}s <7200s: PASS. Actual all-cell Phase B {lock['phase_b_seconds']:.3f}s. All33 original-grid alphas match. All24 cells with stored TRAIN/VAL predictions are EXACT. The nine archived W3 O cells defer their forecast replay to Phase C. All selections and candidate VAL MSEs were locked before TEST_UNLOCK.json; the Phase B read ledger records only selected TRAIN/VAL slices. A separate 18-cell shrinkage VAL gate was also sealed before TEST reads.\n", 'The TEST guard follows the Step22D/22G distinction between permitted opaque byte hashing and prohibited empirical TEST deserialization: pandas readers are allowlisted; full mixed NPY packs can only be mmap-opened from the TRAIN/VAL selector and sliced before copying. Python audit hooks prohibit source writes and require exclusive new-file opens during fitting/prediction. No power-connection gate was imposed; the user explicitly allowed running on battery.\n', '## Environment\n', '```json\n'+json.dumps(env,indent=2)+'\n```\n', '## Phase A inventory and downstream sources\n', table(inv,['cell_id','window','input_set','config','h','target','old_alpha','old_boundary','alpha_source','train','val','test_source']), 'Full fitted-object/history/canonical/tensor provenance and every consumer are in '+link('INVENTORY_STEP26.csv')+' and '+link('CONSUMERS_STEP26.csv')+'. The inventory is18 W3 raw-target fits,12 W1/W2 Daily+Weekly raw-target fits, and3 W3 C Daily+Weekly CS-target fits from Step22G. Archived W3 O alpha metadata comes specifically from dataset/audit/main_v2/ridge/panel_ridge_summary_metrics.csv, not the obsolete root summary with different split counts. Eight O cells selected100 and Daily-only h20 selected10. Across O/C, the original claim100 in16 of 18 primary cells is confirmed.\n', 'The source audit traces Step5/Step16 forecast skill and738-cell joint Holm families (plus the archived708-primary family), TS/XS and moment MSE decompositions, Step21 DA, Step17 shrinkage with 414 entries per regime, B2 rolling ratios and Step16 stock/volatility/subperiod diagnostics, Step22D pooled three-window IC and its original six-test families, Step8 portfolio allocation/cost/alpha/CE code, Step22G CS metrics/top5 portfolios, and Step18/19 tables/Figure3. No additional reported deterministic Ridge fit was found beyond these33 cells.\n', '## B1 original-grid reproduction\n',table(repro,['cell_id','old_alpha','reproduced_alpha','alpha_equal','train_max_abs_delta','train_class','val_max_abs_delta','val_class']), 'Post-lock TEST comparison for every cell:\n',table(testrepro,['cell_id','max_abs_delta','classification','deferred_W3_O']), 'EXACT means max|delta|<1e-7; NEAR means<1e-5; otherwise DIFFERENT. Prediction comparisons align exact ticker/date keys; labels are also checked. All24 nonarchived TEST replays are exactly equal at the stored precision.\n', '## Phase B selections\n',f"{changed} of 33 cells change alpha;16 of 18 primary raw-target cells change. One selection remains at the hard cap: W1/C/Daily+Weekly/h5/raw, alpha1e12, BOUNDARY_AT_CAP. It is retained without choosing a different penalty. No selection hits the lower cap. The old100-in16/18 claim becomes100-in1/18 with the new grid.\n",table(selection,['cell_id','old_alpha','selected_alpha','val_mse','number_extensions','interior','status','extension_log']), 'Every VAL MSE at every evaluated alpha is recorded in SELECTION_LOCK.csv (val_mse_by_alpha) and each cell’s extended_grid_trials.csv. All extension decisions are fixed before TEST. Independent direct-loop selection agrees for all 33 cells and all trial losses (maximum difference0).\n', '## Phase C TEST metrics for every cell\n',table(wide,['cell_id','mse_old','mse_new','r2os_vs_global_train_mean_old','r2os_vs_global_train_mean_new','mean_rank_ic_old','mean_rank_ic_new','da_excluding_zero_old','da_excluding_zero_new']), 'All old/new fields—including R2 vs Zero, CW mean/SE/t/NW/MBB p, IC NW lag h and MBB p, TS/XS decomposition, bias²/Var/Cov decomposition, forecast means/SD and XS R2—are side-by-side at full precision in '+link('OLD_NEW_TEST_METRICS_STEP26.csv')+'. The long-form values and date series are in TEST_METRICS_STEP26.csv and DATE_SERIES_STEP26.csv. CW uses lag h−1, IC uses lag h, original overlapping date blocks L=h andB20000. R2 uses each window’s own TRAIN-mean reference. DA excludes exactly-zero targets. CS MSE/DA use float64 date-demeaned targets; rank correlation agrees with the corresponding raw-return ranks.\n', '## Joint forecast-skill Holm propagation\n', 'The original738-cell and708-primary families are corrected using their original code conventions. All non-Ridge raw values are copied. **No forecast-skill Holm rejection changes, for Ridge or any other model.** In the738-cell view, positive R2 against GTM rises7→17 and nominal IC-MBB p<.05 rises42→43; Holm-significant CW and IC counts remain0. Full old/new raw and adjusted values for every family member are in HOLM_COMPARISON_STEP26.csv.\n', '## Shrinkage toward the training mean\n','All18 Ridge Daily+Weekly cells now have validation-selected shrinkage, including the formerly N/A W3 O cells. The original grid lambda0,.1,...,1, strict first minimum, training-mean arithmetic, and fixed-lambda .5 sensitivity are reused. Original non-Ridge raw statistics remain fixed; each original 414-entry loss family is recorrected. No combined forecast significantly improves on the training mean. Four SECONDARY Ridge rejections for deterioration disappear (W1 O h5/10/20 andW3 C h5); no non-Ridge rejection changes.\n',table(read('OLD_NEW_SHRINKAGE_STEP26.csv'),['regime','cell_id','lambda_used_old','lambda_used_new','test_mse_old','test_mse_new','loss_p_Holm_old','loss_p_Holm_new']), 'All shrinkage MSE, both R2 values, Rank IC, loss intervals/p and refreshed original-family CW references are in '+link('OLD_NEW_SHRINKAGE_STEP26.csv')+'; the full828-row family is propagated/SHRINKAGE_final_step26.csv.\n','## Rolling windows, stock, volatility and subperiods\n','Own-window references, original TRAIN volatility terciles and195/196-date subperiods are retained. Subgroup IC uses only dates with at least5 stocks; single-stock cross-sectional IC stays N/A. Complete old/new values for all 396 Ridge subgroup rows are in OLD_NEW_SUBGROUPS_SUMMARY_STEP26.csv and OLD_NEW_SUBGROUPS_PER_SEED_STEP26.csv. PLUG W1 O relative MSE falls from the reported26–57 range to0.991346–0.997501; its mean bias is now positive0.008984–0.042038. The old severe price-level extrapolation-failure example no longer applies to this Ridge grid.\n',table(read('OLD_NEW_ROLLING_CW_STEP26.csv'),['window','input_set','h','reference','cw_mean_old','cw_mean_new','p_nw_holm_3h_old','p_nw_holm_3h_new','p_mbb_holm_3h_old','p_mbb_holm_3h_new']), 'All rolling CW mean/t/raw p values are also in '+link('OLD_NEW_ROLLING_CW_STEP26.csv')+'. Full non-Ridge subgroup/CW rows are preserved in propagated/ outputs.\n','## Pooled three-window Rank IC and original families\n',table(read('OLD_NEW_POOLED_STEP26.csv'),['window','input_set','h','mse_old','mse_new','mean_old','mean_new','nw_se_old','nw_se_new']), 'Pooled C Ridge IC changes0.041984–0.087053→0.032910–0.062152. Pooled O Ridge IC becomes−0.046193 to−0.025421. Ridge was descriptive in Step22D, outside the six Static/Adaptive tests for each input, so those original NW/MBB Holm families and decisions are copied unchanged; no Ridge test was added to them. Stratified blocks never cross window boundaries; pooled NW variance combines each window variance under the original independence assumption. Full old/new IC confidence intervals, both R2 values and DA are in OLD_NEW_POOLED_STEP26.csv.\n','## Ridge portfolios and480-alpha count\n','The Step8 allocation, Ledoit–Wolf covariance, gamma grid, cap, stable ranking, next-session execution, holding/turnover/cost conventions, lag5 alpha regression, Sharpe/drawdown and CE functions are reused. Only Ridge scores change. Original reported Ridge portfolio metrics replay within4.99e-9. CS portfolios reuse the original Step22G top5 long-only and top5-minus-bottom5 code: long100%/short100%, gross200%, net0, 10bp per unit full-book L1 turnover; they exclude borrowing costs and cash interest and remain descriptive.\n',table(read('PRICE_LEVEL_480_ALPHA_COUNT_STEP26.csv'),['arm','n_combinations','n_abs_t_gt_1_96']), 'Only the84 O Ridge strategy/cost rows replace entries in the original portfolio table; all non-Ridge alpha statistics remain fixed. At O/h5/gamma5/10bp, Sharpe changes1.316974→1.079415 and annual turnover56.470547→2.417183; the old “about56 times” narrative does not hold. Every Sharpe/turnover/MDD/alpha/CE value, for all costs and gammas, is paired in OLD_NEW_PORTFOLIOS_STEP26.csv; CS values are in OLD_NEW_CS_PORTFOLIOS_STEP26.csv. Full weights, daily returns, rebalances and optimizer diagnostics are retained.\n', '## Phase D manuscript impact and regenerated artifacts\n', f"The manuscript and response letter in revision_work/inputs/step26/ were read only. OOXML extraction retains paragraph and native table/row/cell locations. The complete impact inventory has{len(impact)} rows: {dict(impactcounts)}. Use **IMPACT_STEP26_COMPLETE.csv** as the complete deliverable; IMPACT_STEP26.csv is the retained immutable first pass, supplemented by one contextual sentence (“Its penalty is selected from four candidate values…”). No original document was edited.\n", '- Required revisions include the penalty grid/budget/selection count, all Ridge Table4 entries and six Figure3 points, the7→17 positive-R2 and42→43 nominal-IC counts, the old O-to-C Ridge accuracy-gain statements, Ridge rolling/PLUG examples, pooled Ridge IC ranges, Ridge portfolio interpretation and7→5 alpha count. The forecast-skill Holm nonrejection and no-significant-shrinkage-improvement conclusions hold. The “no model beats Zero in any window” statement is no longer true descriptively: W3 O Daily+Weekly Ridge has positive R2 versus Zero at all three horizons. The claim about the lowest learned O MSE must now include deterministic Ridge, compared with saved neural seed means.\n', '- Table generation reuses the original Step19 exclusive CSV exporter; Figure3 reuses the original full-precision ratio-construction and plotting/save block. Other-model points and error bars use the original saved summaries. Figure3 PNG was visually inspected and the original canvas-bound assertions passed. New artifacts carry the requested _step26 suffix. S10/S11 originally omitted O Ridge; the84 O Ridge rows are explicitly added from the requested Step8 grid. S13 andS18 have full updated metric views in addition to their Ridge-only extracts.\n', '\n'.join('- '+link(str(p.relative_to(OUT))) for p in sorted((OUT/'manuscript').iterdir()) if p.is_file())+'\n','## Deviations and retained implementation attempts\n', '1. Before selection, code/provenance inspection displayed the prior B2 report and historical Ridge summary rows containing aggregate TEST metrics. No TEST labels or predictions were read; this deviated from the broader protocol wording banning performance records, but not from the user’s explicit label/prediction lock. All grid/extension rules remained pre-registered and unchanged.\n','2. The preregistration’s generic “numerical reproduction failure” sentence was broader than the explicit user B1 rule. After the deferred O TEST failures, work continued under the user’s explicit instruction to report those results and stop only for DIFFERENT stored VAL. No post-TEST fitting/penalty change occurred other than the pre-declared independent all-cell validation. The O limitation is disclosed throughout.\n','3. The input directory was initially absent, found at revision_work/step26/, then moved by the user to the exact requested inputs path. The original files were never moved or altered by the assistant. Path and byte checks are both reported.\n','4. Two portfolio adapter preflight attempts failed before any portfolio metric was emitted (calendar key type; selecting the validation loop rather than the strategy loop). Corrected source-bound adapter v3 reran the entire prescribed portfolio set. Old scripts and failure records remain. No Ridge fit was selectively retrained or retried.\n','5. The full Step8 loop also computed12 C top3 strategy/cost rows per arm that were excluded in the reported Step16 C set. They are retained in the exhaustive portfolio audit and are not used for the regenerated C S10/S11 rows or the480 O alpha count. This source-scope deviation did not select any model or strategy after outcomes.\n','6. Preliminary helper/impact versions remain immutable. Final entrypoints and canonical outputs are explicitly identified; no file was overwritten. Default-solver ill-conditioning warnings at small alphas were retained as observations; no alternate solver, dtype or thread tuning was substituted.\n','## Runtime and preservation\n',f"Phase B all 33 cells: {lock['phase_b_seconds']:.3f}s. First-three projection: {js('TIMING_GATE.json')['projection_seconds']:.3f}s. Elapsed protocol-registration to report generation: {elapsed:.1f}s ({elapsed/60:.2f}min), including implementation, all-cell independent refits, inference, propagation, figures and repeated full-repository hash scans. The entire session remained below2hours. The independent selection run was not separately timed; no unmeasured per-phase runtime is invented.\n",f"Final hash audit: {preserve['n_records']:,} pre-existing path records; {preserve['n_records']-3:,} unchanged at their original paths;3 externally relocated files with identical destination bytes;0 other content changes. Full per-path verification is FINAL_PREEXISTING_VERIFICATION.jsonl, summary FINAL_PREEXISTING_PRESERVATION_CHECK.json. Thus all original file contents/link targets are accounted for unchanged, but it would be false to claim every original pathname is unchanged.\n", '## Every new file and SHA-256\n','The table below lists every file present before this report. FINAL_ARTIFACT_SHA256.csv additionally includes this report and FILES_BEFORE_REPORT_STEP26.csv. Its detached .sha256 records the final manifest hash; a manifest does not self-hash. The standard detached-hash endpoint avoids an impossible infinite self-reference.\n',table(manifest,['path','bytes','sha256']), '## Plain-language summary\n',f"The extended grid changed the selected Ridge penalty in {changed} of the33 reported fits, including 16 of the18 primary-window fits. One rolling-window selection remains at the pre-registered upper cap of1e12 and is reported as a boundary case. Every available TRAIN/VAL forecast reproduced exactly, and independent validation confirmed all selections and W3 TEST MSE/Rank IC calculations; the nine archived price-level TEST replays have the disclosed numerical limitation. Much stronger regularization removes the previously severe price-level Ridge errors and the PLUG example, so several claims that window-relative features improve Ridge accuracy no longer hold. The pooled window-relative Ridge ranking signal is smaller, and the price-level portfolio turnover is much lower than the manuscript currently states. No joint forecast-skill Holm decision changes, the shrinkage analysis still finds no significant accuracy improvement over the training mean, and the count of price-level alpha statistics above the absolute1.96 threshold falls from 7 to 5 out of 480. Updated tables, Figure3 and a complete sentence/cell impact inventory are saved as new files, while all original file bytes are preserved, with the user’s input-folder relocation documented.\n"]
 write('REPORT_STEP26_RIDGE_GRID.md','\n'.join(r))
 # Final manifest includes all reports and all earlier new artifacts, excluding only itself and its detached hash.
 final=[dict(path=str(p.relative_to(OUT)),bytes=p.stat().st_size,sha256=sha(p)) for p in sorted(OUT.rglob('*')) if p.is_file()]
 with (OUT/'FINAL_ARTIFACT_SHA256.csv').open('x',newline='') as f:
  w=csv.DictWriter(f,fieldnames=['path','bytes','sha256']);w.writeheader();w.writerows(final)
